
import "@supabase/functions-js/edge-runtime.d.ts";
import { withSupabase } from "@supabase/server";

/**
 * Portrait Atelier — Enquiry submission.
 *
 * Validates customer details, saves enquiries,
 * and prevents duplicate submissions.
 *
 * Upload tokens are generated by the frontend.
 * Only their SHA-256 hashes are stored in PostgreSQL.
 */

const MAX_BODY_BYTES = 32 * 1024;
const MAX_NAME_LENGTH = 120;
const MAX_EMAIL_LENGTH = 254;
const MAX_MESSAGE_LENGTH = 3000;
const MAX_CHOICES_BYTES = 16 * 1024;

const UPLOAD_TOKEN_LIFETIME_MS = 24 * 60 * 60 * 1000;

interface EnquiryPayload {
  submissionKey: string;
  uploadToken: string;
  customerName: string;
  customerEmail: string;
  customerMessage?: string;
  portraitChoices: Record<string, unknown>;
}

interface StoredEnquiry {
  id: string;
  customer_name: string;
  customer_email: string;
  customer_message: string | null;
  portrait_choices: Record<string, unknown>;
  upload_token_hash: string | null;
  upload_expires_at: string | null;
}

type FieldErrors = Record<string, string>;

/**
 * Checks whether a value is a plain object.
 */
function isRecord(
  value: unknown,
): value is Record<string, unknown> {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value)
  );
}

/**
 * Returns JSON without allowing response caching.
 */
function jsonResponse(
  body: Record<string, unknown>,
  status: number,
): Response {
  return Response.json(body, {
    status,
    headers: {
      "Cache-Control": "no-store",
    },
  });
}

/**
 * Checks and normalises customer enquiry data.
 */
function validateEnquiry(value: unknown): {
  payload: EnquiryPayload | null;
  errors: FieldErrors;
} {
  if (!isRecord(value)) {
    return {
      payload: null,
      errors: {
        form: "Please provide an enquiry object.",
      },
    };
  }

  const errors: FieldErrors = {};

  const submissionKey =
    typeof value.submissionKey === "string"
      ? value.submissionKey
      : "";

  const uploadToken =
    typeof value.uploadToken === "string"
      ? value.uploadToken
      : "";

  const name =
    typeof value.customerName === "string"
      ? value.customerName.trim()
      : "";

  const email =
    typeof value.customerEmail === "string"
      ? value.customerEmail.trim()
      : "";

  const message =
    typeof value.customerMessage === "string"
      ? value.customerMessage.trim()
      : "";

  // Validate the unique submission identifier.
  if (
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      submissionKey,
    )
  ) {
    errors.submissionKey =
      "Invalid submission identifier.";
  }

  // The upload token is a 32-byte random value
  // encoded using unpadded Base64URL.
  if (!/^[A-Za-z0-9_-]{43}$/.test(uploadToken)) {
    errors.uploadToken = "Invalid upload token.";
  }

  if (
    name.length < 2 ||
    name.length > MAX_NAME_LENGTH
  ) {
    errors.customerName =
      "Enter your name (2–120 characters).";
  }

  if (
    email.length > MAX_EMAIL_LENGTH ||
    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
  ) {
    errors.customerEmail =
      "Enter a valid email address.";
  }

  if (
    value.customerMessage !== undefined &&
    typeof value.customerMessage !== "string"
  ) {
    errors.customerMessage =
      "Your message must be text.";
  } else if (message.length > MAX_MESSAGE_LENGTH) {
    errors.customerMessage =
      "Your message is too long (maximum 3,000 characters).";
  }

  if (!isRecord(value.portraitChoices)) {
    errors.portraitChoices =
      "Portrait choices are required.";
  } else if (
    new TextEncoder().encode(
      JSON.stringify(value.portraitChoices),
    ).length > MAX_CHOICES_BYTES
  ) {
    errors.portraitChoices =
      "Portrait choices are too large.";
  }

  if (Object.keys(errors).length > 0) {
    return {
      payload: null,
      errors,
    };
  }

  return {
    payload: {
      submissionKey,
      uploadToken,
      customerName: name,
      customerEmail: email,
      customerMessage: message,
      portraitChoices:
        value.portraitChoices as Record<string, unknown>,
    },
    errors: {},
  };
}

/**
 * Generates a SHA-256 hash of the upload token.
 *
 * The original token is never saved in PostgreSQL.
 */
async function hashUploadToken(
  token: string,
): Promise<string> {
  const bytes = new TextEncoder().encode(token);

  const digest = await crypto.subtle.digest(
    "SHA-256",
    bytes,
  );

  return Array.from(new Uint8Array(digest))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

/**
 * Checks whether an existing enquiry belongs to
 * this exact submission.
 *
 * A matching submission key alone is insufficient.
 * The upload token and enquiry details must match.
 */
function matchesExistingEnquiry(
  existing: StoredEnquiry,
  payload: EnquiryPayload,
  tokenHash: string,
): boolean {
  return (
    existing.upload_token_hash === tokenHash &&
    existing.customer_name === payload.customerName &&
    existing.customer_email === payload.customerEmail &&
    (existing.customer_message ?? "") ===
      (payload.customerMessage ?? "") &&
    JSON.stringify(existing.portrait_choices) ===
      JSON.stringify(payload.portraitChoices)
  );
}

/**
 * Produces the response expected by the frontend.
 */
function successResponse(
  enquiryId: string,
  uploadToken: string,
  uploadExpiresAt: string,
  isRetry: boolean,
): Response {
  return jsonResponse(
    {
      success: true,
      validated: true,
      saved: true,
      enquiryId,
      uploadToken,
      uploadExpiresAt,
      reused: isRetry,
      message: isRetry
        ? "Existing enquiry recovered successfully."
        : "Enquiry saved successfully.",
    },
    isRetry ? 200 : 201,
  );
}

export default {
  fetch: withSupabase(
    { auth: "publishable" },
    async (request, ctx) => {
      if (request.method !== "POST") {
        return jsonResponse(
          {
            success: false,
            code: "METHOD_NOT_ALLOWED",
            message: "Use POST.",
          },
          405,
        );
      }

      const contentType = request.headers
        .get("content-type")
        ?.toLowerCase();

      if (!contentType?.includes("application/json")) {
        return jsonResponse(
          {
            success: false,
            code: "UNSUPPORTED_MEDIA_TYPE",
            message: "Send a JSON enquiry.",
          },
          415,
        );
      }

      const declaredLength = Number(
        request.headers.get("content-length") ?? "0",
      );

      if (declaredLength > MAX_BODY_BYTES) {
        return jsonResponse(
          {
            success: false,
            code: "PAYLOAD_TOO_LARGE",
            message: "Enquiry data is too large.",
          },
          413,
        );
      }

      let input: unknown;

      try {
        const raw = await request.text();

        if (
          new TextEncoder().encode(raw).length >
          MAX_BODY_BYTES
        ) {
          return jsonResponse(
            {
              success: false,
              code: "PAYLOAD_TOO_LARGE",
              message: "Enquiry data is too large.",
            },
            413,
          );
        }

        input = JSON.parse(raw) as unknown;
      } catch {
        return jsonResponse(
          {
            success: false,
            code: "INVALID_JSON",
            message: "The enquiry is not valid JSON.",
          },
          400,
        );
      }

      const { payload, errors } =
        validateEnquiry(input);

      if (!payload) {
        return jsonResponse(
          {
            success: false,
            code: "VALIDATION_FAILED",
            message: "Please check your details.",
            errors,
          },
          422,
        );
      }

      try {
        const uploadTokenHash =
          await hashUploadToken(payload.uploadToken);

        const uploadExpiresAt = new Date(
          Date.now() + UPLOAD_TOKEN_LIFETIME_MS,
        ).toISOString();

        // Attempt to save a new enquiry.
        //
        // PostgreSQL has a unique index on submission_key.
        // Only one request with a given key can create a row.
        const { data, error } = await ctx.supabaseAdmin
          .from("portrait_enquiries")
          .insert({
            submission_key: payload.submissionKey,
            customer_name: payload.customerName,
            customer_email: payload.customerEmail,
            customer_message:
              payload.customerMessage ?? "",
            portrait_choices: payload.portraitChoices,
            upload_token_hash: uploadTokenHash,
            upload_expires_at: uploadExpiresAt,
          })
          .select("id")
          .single();

        if (!error && data?.id) {
          return successResponse(
            data.id,
            payload.uploadToken,
            uploadExpiresAt,
            false,
          );
        }

        // PostgreSQL error 23505 means a unique constraint
        // was violated. This may be a repeated submission.
        if (error?.code !== "23505") {
          return jsonResponse(
            {
              success: false,
              saved: false,
              code: "SAVE_FAILED",
              message:
                "The enquiry could not be saved. Please try again later.",
            },
            500,
          );
        }

        // Retrieve the existing enquiry using its submission key.
        const { data: existing, error: lookupError } =
          await ctx.supabaseAdmin
            .from("portrait_enquiries")
            .select(
              "id, customer_name, customer_email, customer_message, portrait_choices, upload_token_hash, upload_expires_at",
            )
            .eq("submission_key", payload.submissionKey)
            .maybeSingle();

        if (lookupError || !existing) {
          return jsonResponse(
            {
              success: false,
              saved: false,
              code: "SAVE_FAILED",
              message:
                "The enquiry could not be recovered. Please try again.",
            },
            500,
          );
        }

        // A repeated submission must prove that it has
        // the same upload token and unchanged enquiry data.
        if (
          !matchesExistingEnquiry(
            existing as StoredEnquiry,
            payload,
            uploadTokenHash,
          )
        ) {
          return jsonResponse(
            {
              success: false,
              code: "SUBMISSION_CONFLICT",
              message:
                "This submission has already been used with different details.",
            },
            409,
          );
        }

        // Keep the ORIGINAL expiry time.
        // A retry must not extend upload permissions.
        if (
          !existing.upload_expires_at ||
          new Date(existing.upload_expires_at).getTime() <=
            Date.now()
        ) {
          return jsonResponse(
            {
              success: false,
              code: "UPLOAD_PERMISSION_EXPIRED",
              message:
                "The upload permission has expired. Please contact us.",
            },
            403,
          );
        }

        // Return the original enquiry rather than
        // creating a duplicate.
        return successResponse(
          existing.id,
          payload.uploadToken,
          existing.upload_expires_at,
          true,
        );
      } catch {
        return jsonResponse(
          {
            success: false,
            saved: false,
            code: "SAVE_FAILED",
            message:
              "The enquiry could not be saved. Please try again later.",
          },
          500,
        );
      }
    },
  ),
};
